INSERT INTO complaint_form(id,title,description,fields) VALUES(1,'Жалоба на сотрудника','Заполните форму — жалоба будет рассмотрена Военной Полицией','[{"key":"submitter_fio","label":"Ваше ФИО","type":"text","required":true,"placeholder":"Иван Иванов","order":10,"group":"Ваши данные"},{"key":"submitter_static","label":"Ваш статик","type":"text","required":true,"placeholder":"123-456","order":20,"group":"Ваши данные"},{"key":"submitter_discord","label":"Ваш @тег Discord","type":"text","required":false,"placeholder":"@username или ID","order":30,"group":"Ваши данные"},{"key":"target_fio","label":"ФИО нарушителя","type":"text","required":false,"placeholder":"Пётр Петров","order":40,"group":"Данные нарушителя"},{"key":"target_static","label":"Статик нарушителя","type":"text","required":true,"placeholder":"789-012","order":50,"group":"Данные нарушителя"},{"key":"description","label":"Суть нарушения","type":"textarea","required":true,"placeholder":"Опишите, что произошло, где и когда","order":60,"group":"Обстоятельства"},{"key":"norms","label":"Нарушенные нормы (ВУ ВС РФ, УК, ПК и иные)","type":"textarea","required":true,"placeholder":"Например: ст. 12 ВУ ВС РФ, п.3 ПК","order":70,"group":"Обстоятельства"},{"key":"evidence_url","label":"Доказательства нарушения","type":"text","required":true,"placeholder":"https:// (ссылка на видео/скриншот)","order":80,"group":"Обстоятельства"}]') ON CONFLICT(id) DO NOTHING;
